"use client";

import { useReducedMotion } from "motion/react";
import { useId, useRef, useState } from "react";

import { SegmentedControl } from "@/components/motion/segmented-control";
import { Button } from "@/components/ui/button";

import { formatWhole } from "../lib/format";
import { BlockFrame } from "../parts/block-frame";
import { MaximizeIcon, PlusIcon } from "../parts/icons";
import { MinusIcon } from "./icons";
import { WEEK_POSE } from "./activity-terrain/camera";
import { LEGEND_STOPS, rampColour } from "./activity-terrain/colour";
import {
  DAYS,
  hourLabel,
  TERRAIN_METRICS,
  type TerrainMetricId,
  WEEK_LABEL,
} from "./activity-terrain/data";
import {
  type TerrainCell,
  TerrainStage,
} from "./activity-terrain/terrain-stage";
import {
  TerrainSummary,
  TerrainTable,
} from "./activity-terrain/terrain-summary";
import { useTerrainMotion } from "./activity-terrain/use-terrain-motion";
import { useInView } from "./lib/use-in-view";

type View = "angled" | "flat";

const VIEWS: { value: View; label: string }[] = [
  { value: "angled", label: "Terrain" },
  { value: "flat", label: "Heatmap" },
];

/**
 * A week of clinic activity as a terrain: one column per hour of each day,
 * as tall as that hour was busy. A person picks a figure, turns and zooms
 * the camera, flies in to one hour, or flattens the terrain into a heatmap.
 * A table and three figures give the same data in text.
 */
export function ActivityTerrain({ className }: { className?: string }) {
  const [metricId, setMetricId] = useState<TerrainMetricId>("bookings");
  const [view, setView] = useState<View>("angled");
  const [cursor, setCursor] = useState<TerrainCell | null>(null);
  const titleId = useId();
  const stageBox = useRef<HTMLDivElement>(null);
  const inView = useInView(stageBox);
  const reduceMotion = useReducedMotion() ?? false;

  const metric =
    TERRAIN_METRICS.find((item) => item.id === metricId) ?? TERRAIN_METRICS[0]!;
  const motion = useTerrainMotion(
    metric.hours,
    view === "flat",
    reduceMotion,
    inView,
  );
  const zoom = motion.target.current.zoom;

  const readout = cursor
    ? `${DAYS[cursor.day]}, ${hourLabel(cursor.hour)}: ${formatWhole(metric.hours[cursor.day]?.[cursor.hour] ?? 0)} ${metric.noun}.`
    : `Showing the whole week of ${metric.noun}.`;

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-start justify-between gap-x-6 gap-y-3 px-5 pt-5">
        <div className="min-w-0">
          <h2 id={titleId} className="text-base font-semibold">
            When the clinics are busy
          </h2>
          <p className="text-sm text-muted-foreground">
            {WEEK_LABEL}, every Fernhill clinic, hour by hour.
          </p>
        </div>
        <SegmentedControl
          aria-label="View"
          options={VIEWS}
          value={view}
          onValueChange={setView}
        />
      </header>

      <div className="flex flex-wrap items-center justify-between gap-3 px-5 pt-4">
        <SegmentedControl
          aria-label="Figure"
          options={TERRAIN_METRICS.map((item) => ({
            value: item.id,
            label: item.label,
          }))}
          value={metricId}
          onValueChange={setMetricId}
        />
        <div
          className="flex items-center gap-2 text-xs text-muted-foreground"
          aria-hidden="true"
        >
          Fewer
          <svg viewBox="0 0 76 12" className="h-3 w-19">
            {LEGEND_STOPS.map((stop, index) => (
              <rect
                key={stop}
                x={index * 16}
                width={12}
                height={12}
                rx={3}
                fill={rampColour(stop)}
              />
            ))}
          </svg>
          More
        </div>
      </div>

      <div ref={stageBox} className="relative px-3 pt-2 pb-3">
        <TerrainStage
          hours={metric.hours}
          motion={motion}
          cursor={cursor}
          onCursor={setCursor}
          label={`${metric.label} terrain. Arrows move the highlighted hour, Shift and arrows turn, plus and minus zoom, Enter flies in, Escape shows the whole week.`}
        />
        <div className="absolute right-5 bottom-5 flex gap-1">
          <Button
            variant="outline"
            size="icon"
            aria-label="Zoom out"
            onClick={() => motion.aim({ zoom: zoom / 1.25 })}
          >
            <MinusIcon className="size-4" />
          </Button>
          <Button
            variant="outline"
            size="icon"
            aria-label="Zoom in"
            onClick={() => motion.aim({ zoom: zoom * 1.25 })}
          >
            <PlusIcon aria-hidden="true" className="size-4" />
          </Button>
          <Button
            variant="outline"
            size="icon"
            aria-label="Show the whole week"
            onClick={() => {
              setCursor(null);
              motion.aim({ x: 0, z: 0, zoom: WEEK_POSE.zoom });
            }}
          >
            <MaximizeIcon aria-hidden="true" className="size-4" />
          </Button>
        </div>
        <p
          className="absolute bottom-6 left-6 hidden max-w-[60%] text-xs text-muted-foreground @md:block"
          aria-hidden="true"
        >
          Drag to turn, pinch to zoom, click a column to fly in.
        </p>
      </div>

      <p role="status" className="px-5 pb-3 text-sm text-muted-foreground">
        {readout}
      </p>
      <TerrainTable metric={metric} />
      <TerrainSummary metric={metric} />
    </BlockFrame>
  );
}

const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const ONE_PLACE = new Intl.NumberFormat("en-US", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const COMPACT = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const MONEY = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });

/** A whole number with thousands separators. */
export const formatWhole = (value: number) => WHOLE.format(Math.round(value));

/** A number with one decimal place. */
export const formatOnePlace = (value: number) => ONE_PLACE.format(value);

/** A short number for an axis, such as 1.2K. */
export const formatCompact = (value: number) => COMPACT.format(value);

/** A dollar amount with no cents. */
export const formatMoney = (value: number) => MONEY.format(Math.round(value));

/** A percent with one decimal place and no sign. */
export const formatPercent = (value: number) => `${ONE_PLACE.format(Math.abs(value))}%`;

const DAY = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
const WEEKDAY = new Intl.DateTimeFormat("en-US", { weekday: "long", timeZone: "UTC" });

/** The sample data ends on this day, so every block shows the same dates on every render. */
export const SAMPLE_END = Date.UTC(2026, 9, 31);

/** The date `daysBeforeEnd` days before the last sample day. */
export const sampleDate = (daysBeforeEnd: number) => new Date(SAMPLE_END - daysBeforeEnd * 86_400_000);

/** A short date, such as Oct 31. */
export const formatDay = (date: Date) => DAY.format(date);

/** A weekday name, such as Tuesday. */
export const formatWeekday = (date: Date) => WEEKDAY.format(date);

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

