import { type SpringValue, springAt } from "../lib/spring";

/** Where the camera looks from. Angles are in radians, `zoom` is a multiplier. */
export interface CameraPose {
  yaw: number;
  pitch: number;
  zoom: number;
  /** The point on the floor the camera centres on, in grid units. */
  x: number;
  z: number;
}

/** The camera's springs, one per part of the pose. */
export type CameraSprings = { [Key in keyof CameraPose]: SpringValue };

/** The pose that shows the whole week at an angle. */
export const WEEK_POSE: CameraPose = {
  yaw: -0.5,
  pitch: 0.62,
  zoom: 1,
  x: 0,
  z: 0,
};

/** The pose that looks straight down, so the terrain reads as a heatmap. */
export const TOP_POSE: CameraPose = {
  yaw: 0,
  pitch: Math.PI / 2,
  zoom: 1.08,
  x: 0,
  z: 0,
};

/** The lowest and highest camera tilt. */
export const PITCH_LIMITS: [number, number] = [0.3, Math.PI / 2];

/** The drawing box of the stage, in SVG units. */
export const STAGE = { width: 800, height: 440 };

/** Makes resting springs at a pose. */
export const springsAt = (pose: CameraPose): CameraSprings => ({
  yaw: springAt(pose.yaw),
  pitch: springAt(pose.pitch),
  zoom: springAt(pose.zoom),
  x: springAt(pose.x),
  z: springAt(pose.z),
});

/** Reads the current pose out of the springs. */
export const poseOf = (springs: CameraSprings): CameraPose => ({
  yaw: springs.yaw.value,
  pitch: springs.pitch.value,
  zoom: springs.zoom.value,
  x: springs.x.value,
  z: springs.z.value,
});

/** A point on screen, with its depth: a larger depth is nearer the viewer. */
export interface ScreenPoint {
  sx: number;
  sy: number;
  depth: number;
}

/**
 * Projects a point of the grid, in grid units with y up, onto the stage.
 * The camera turns around the vertical axis, then tilts down, with a light
 * perspective so near columns read a little larger.
 */
export function project(
  pose: CameraPose,
  x: number,
  y: number,
  z: number,
): ScreenPoint {
  const dx = x - pose.x;
  const dz = z - pose.z;
  const cos = Math.cos(pose.yaw);
  const sin = Math.sin(pose.yaw);
  const rx = dx * cos - dz * sin;
  const rz = dx * sin + dz * cos;
  const tilt = Math.cos(pose.pitch);
  const down = Math.sin(pose.pitch);
  const depth = rz * tilt + y * down;
  const perspective = 60 / (60 - depth);
  const scale = (STAGE.width / 30) * pose.zoom * perspective;
  return {
    sx: STAGE.width / 2 + rx * scale,
    sy: STAGE.height * 0.52 + (rz * down - y * tilt) * scale,
    depth,
  };
}

/** One painted face of a column, as SVG points. */
export interface ColumnFace {
  points: string;
  kind: "top" | "side" | "front";
}

const HALF = 0.41;

/** The grid position of one day and hour: hours run left to right, days front to back. */
export const cellCentre = (day: number, hour: number) => ({
  x: hour - 11.5,
  z: day - 3,
});

const toPoints = (corners: ScreenPoint[]) =>
  corners
    .map((point) => `${point.sx.toFixed(1)},${point.sy.toFixed(1)}`)
    .join(" ");

// A face faces the viewer when its corners run clockwise on screen.
const facesViewer = (a: ScreenPoint, b: ScreenPoint, c: ScreenPoint) =>
  (b.sx - a.sx) * (c.sy - a.sy) - (b.sy - a.sy) * (c.sx - a.sx) < 0;

/** Builds the visible faces of one column of height `height`, and its depth for sorting. */
export function columnFaces(
  pose: CameraPose,
  day: number,
  hour: number,
  height: number,
) {
  const { x, z } = cellCentre(day, hour);
  const footprint: [number, number][] = [
    [x - HALF, z - HALF],
    [x + HALF, z - HALF],
    [x + HALF, z + HALF],
    [x - HALF, z + HALF],
  ];
  const base = footprint.map(([px, pz]) => project(pose, px, 0, pz));
  const top = footprint.map(([px, pz]) => project(pose, px, height, pz));
  const faces: ColumnFace[] = [];
  if (height > 0.02) {
    for (let index = 0; index < 4; index++) {
      const next = (index + 1) % 4;
      const corners = [base[index]!, base[next]!, top[next]!, top[index]!];
      if (facesViewer(corners[0]!, corners[1]!, corners[2]!))
        faces.push({
          points: toPoints(corners),
          kind: index % 2 === 0 ? "side" : "front",
        });
    }
  }
  faces.push({ points: toPoints(top), kind: "top" });
  const centre = project(pose, x, height / 2, z);
  const peak = project(pose, x, height, z);
  return { faces, depth: centre.depth, peak };
}

/** One value pulled toward a target by a spring, with the speed it carries. */
export interface SpringValue {
  value: number;
  velocity: number;
}

/**
 * Moves a spring one step toward `target`. The defaults are close to
 * critically damped, so a value arrives quickly and barely overshoots.
 * Returns true while the value is still moving.
 */
export function stepSpring(
  spring: SpringValue,
  target: number,
  seconds: number,
  stiffness = 170,
  damping = 26,
): boolean {
  // Small sub-steps keep a stiff spring stable on a slow frame.
  const steps = Math.max(1, Math.ceil(seconds / 0.008));
  const dt = seconds / steps;
  for (let index = 0; index < steps; index++) {
    const force =
      (target - spring.value) * stiffness - spring.velocity * damping;
    spring.velocity += force * dt;
    spring.value += spring.velocity * dt;
  }
  const moving =
    Math.abs(target - spring.value) > 0.0005 ||
    Math.abs(spring.velocity) > 0.0005;
  if (!moving) {
    spring.value = target;
    spring.velocity = 0;
  }
  return moving;
}

/** Makes a spring that rests at `value`. */
export const springAt = (value: number): SpringValue => ({
  value,
  velocity: 0,
});

/** Eases a value from 0 to 1 slowly at both ends. */
export const easeInOut = (t: number) =>
  t < 0.5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2;

/** Keeps a value between two bounds. */
export const clamp = (value: number, low: number, high: number) =>
  Math.min(high, Math.max(low, value));

/**
 * The colour of a column whose count is `share` of the busiest hour: green
 * for a quiet hour, blue in the middle and pink at the peak. Every stop is
 * a chart token, so a design system recolours the terrain.
 */
export function rampColour(share: number): string {
  if (share <= 0) return "var(--muted)";
  if (share < 0.5)
    return `color-mix(in oklch, var(--chart-1) ${Math.round(share * 200)}%, var(--chart-2))`;
  return `color-mix(in oklch, var(--chart-5) ${Math.round((share - 0.5) * 200)}%, var(--chart-1))`;
}

/** The same colour in shade, for the side of a column that faces away from the light. */
export const shade = (colour: string, amount: number) =>
  `color-mix(in oklch, ${colour}, oklch(0.15 0 0) ${amount}%)`;

/** The five legend stops, from fewer to more. */
export const LEGEND_STOPS = [0.08, 0.3, 0.5, 0.72, 1];

import { seededRandom } from "../../lib/plot";

/** The figures a person can raise the terrain by. */
export type TerrainMetricId = "bookings" | "checkIns" | "messages";

/** One figure counted for every hour of one week. */
export interface TerrainMetric {
  id: TerrainMetricId;
  label: string;
  /** The noun in a sentence, such as "bookings". */
  noun: string;
  /** Seven rows, Monday first, of 24 hourly counts. */
  hours: number[][];
  /** The total of the week before, for the change figure. */
  lastWeek: number;
}

/** The days of the sample week, Monday first. */
export const DAYS = [
  "Monday",
  "Tuesday",
  "Wednesday",
  "Thursday",
  "Friday",
  "Saturday",
  "Sunday",
];

/** The short day names the terrain prints beside each row. */
export const DAY_SHORT = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

/** The week the terrain shows, as a sentence fragment. */
export const WEEK_LABEL = "Week of 26 October 2026";

/** Writes an hour of the day as "09:00". */
export const hourLabel = (hour: number) =>
  `${String(hour).padStart(2, "0")}:00`;

// How busy each hour of a clinic day is, from 0 to 1. Clinics open at 7 and close at 19, with a lunch dip.
const CLINIC_DAY = [
  0, 0, 0, 0, 0, 0, 0.02, 0.35, 0.8, 1, 0.92, 0.85, 0.55, 0.62, 0.88, 0.9, 0.78,
  0.6, 0.4, 0.12, 0.03, 0, 0, 0,
];
// Messages keep coming in the evening, when patients have time to write.
const MESSAGE_DAY = [
  0.02, 0, 0, 0, 0, 0.02, 0.1, 0.4, 0.7, 0.75, 0.62, 0.55, 0.7, 0.6, 0.5, 0.48,
  0.5, 0.6, 0.72, 0.85, 0.8, 0.55, 0.3, 0.1,
];
// Monday is the heaviest day, Saturday has a morning list, Sunday is nearly closed.
const DAY_WEIGHTS = [1, 0.92, 0.86, 0.9, 0.78, 0.42, 0.08];
const SATURDAY_MORNING = (hour: number) => (hour < 13 ? 1.6 : 0.2);

function makeWeek(
  seed: number,
  peak: number,
  day: number[],
  saturdayWeight: (hour: number) => number,
): number[][] {
  const random = seededRandom(seed);
  return DAY_WEIGHTS.map((dayWeight, dayIndex) =>
    day.map((hourWeight, hour) => {
      const weekend = dayIndex === 5 ? saturdayWeight(hour) : 1;
      const noise = 0.78 + random() * 0.44;
      return Math.round(peak * dayWeight * hourWeight * weekend * noise);
    }),
  );
}

/** The three figures, each one week of hourly counts across every Fernhill clinic. */
export const TERRAIN_METRICS: TerrainMetric[] = [
  {
    id: "bookings",
    label: "Bookings",
    noun: "bookings",
    hours: makeWeek(7, 64, CLINIC_DAY, SATURDAY_MORNING),
    lastWeek: 0,
  },
  {
    id: "checkIns",
    label: "Check-ins",
    noun: "check-ins",
    hours: makeWeek(19, 48, CLINIC_DAY, SATURDAY_MORNING),
    lastWeek: 0,
  },
  {
    id: "messages",
    label: "Messages",
    noun: "messages",
    hours: makeWeek(31, 40, MESSAGE_DAY, () => 0.9),
    lastWeek: 0,
  },
];

// The week before differs by a few percent per figure, so each change figure has its own sign.
const LAST_WEEK_RATIO = {
  bookings: 0.93,
  checkIns: 0.97,
  messages: 1.06,
} satisfies Record<TerrainMetricId, number>;
for (const metric of TERRAIN_METRICS) {
  metric.lastWeek = Math.round(
    metric.hours.flat().reduce((sum, value) => sum + value, 0) *
      LAST_WEEK_RATIO[metric.id],
  );
}

/** The week's total, its busiest day and the hour of the day that is busiest across the week. */
export function readWeek(metric: TerrainMetric) {
  const dayTotals = metric.hours.map((row) =>
    row.reduce((sum, value) => sum + value, 0),
  );
  const total = dayTotals.reduce((sum, value) => sum + value, 0);
  const hourTotals = Array.from({ length: 24 }, (_, hour) =>
    metric.hours.reduce((sum, row) => sum + (row[hour] ?? 0), 0),
  );
  const peakHour = hourTotals.indexOf(Math.max(...hourTotals));
  const busiestDay = dayTotals.indexOf(Math.max(...dayTotals));
  const max = Math.max(...metric.hours.flat());
  return {
    dayTotals,
    total,
    peakHour,
    busiestDay,
    max,
    change: ((total - metric.lastWeek) / metric.lastWeek) * 100,
  };
}

/**
 * Plot maths shared by the blocks. Every path is drawn in a 0 to 100 box, and
 * the SVG stretches it with `preserveAspectRatio="none"`, so a chart needs no
 * resize observer. Strokes keep their width through `vector-effect`.
 */

/** A repeatable random source, so sample data is the same on the server and in the browser. */
export function seededRandom(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state * 1664525 + 1013904223) >>> 0;
    return state / 4294967296;
  };
}

// Monday to Sunday: a working week that tails off, then a quiet weekend.
const WEEKDAY_LIFT = [0.35, 0.5, 0.2, 0.1, -0.05, -0.75, -1];

/** Sample data that moves from `start` to `end` with a working-week rhythm and some noise. */
export function makeSeries(seed: number, length: number, start: number, end: number, noise: number): number[] {
  const random = seededRandom(seed);
  return Array.from({ length }, (_, index) => {
    const progress = length === 1 ? 1 : index / (length - 1);
    const trend = start + (end - start) * progress;
    const week = (WEEKDAY_LIFT[index % 7] ?? 0) * noise * 0.6;
    return Math.max(0, trend + week + (random() - 0.5) * noise * 0.7);
  });
}

/** The lowest and highest value across several series, padded so a line never touches the frame. */
export function paddedExtent(series: number[][], padding = 0.12): [number, number] {
  const values = series.flat();
  const low = Math.min(...values);
  const high = Math.max(...values);
  const span = high - low || 1;
  return [Math.max(0, low - span * padding), high + span * padding];
}

/** Where a value sits in the box, from 0 at the top to 100 at the bottom. */
export function toY(value: number, [low, high]: [number, number]): number {
  return 100 - ((value - low) / (high - low || 1)) * 100;
}

/** Where a point sits across the box, from 0 to 100. */
export function toX(index: number, length: number): number {
  return length <= 1 ? 50 : (index / (length - 1)) * 100;
}

/** The value at a fractional position along a series, read off the straight line between its neighbours. */
function valueAt(values: number[], position: number): number {
  const left = Math.floor(position);
  const right = Math.min(values.length - 1, left + 1);
  const from = values[left] ?? 0;
  const to = values[right] ?? from;
  return from + (to - from) * (position - left);
}

/**
 * A line through `values` with a fixed number of segments. Two paths with the
 * same segment count can morph into each other, whatever their point counts.
 */
export function linePath(values: number[], extent: [number, number], samples = 60): string {
  if (values.length === 0) return "";
  const parts: string[] = [];
  for (let step = 0; step <= samples; step += 1) {
    const position = (step / samples) * (values.length - 1);
    const x = (step / samples) * 100;
    const y = toY(valueAt(values, position), extent);
    parts.push(`${step === 0 ? "M" : "L"}${x.toFixed(2)} ${y.toFixed(2)}`);
  }
  return parts.join(" ");
}

/** The same line, closed down to the bottom edge, for a filled area. */
export function areaPath(values: number[], extent: [number, number], samples = 60): string {
  const line = linePath(values, extent, samples);
  return line ? `${line} L100 100 L0 100 Z` : "";
}

/** Round axis values between the low and high of the plot. */
export function axisTicks([low, high]: [number, number], count = 4): number[] {
  return Array.from({ length: count }, (_, index) => low + ((high - low) * index) / (count - 1));
}

/** The percent change from `before` to `after`, or 0 when there is nothing to compare against. */
export function percentChange(before: number, after: number): number {
  return before === 0 ? 0 : ((after - before) / before) * 100;
}

/** The sum of a series. */
export function sum(values: number[]): number {
  return values.reduce((total, value) => total + value, 0);
}

/** The mean of a series. */
export function mean(values: number[]): number {
  return values.length === 0 ? 0 : sum(values) / values.length;
}

"use client";

import {
  type KeyboardEvent,
  type PointerEvent,
  type WheelEvent,
  useRef,
} from "react";

import { columnFaces, cellCentre, project, STAGE, WEEK_POSE } from "./camera";
import { rampColour, shade } from "./colour";
import { DAY_SHORT, hourLabel } from "./data";
import type { useTerrainMotion } from "./use-terrain-motion";

/** One hour of one day, Monday as day 0. */
export interface TerrainCell {
  day: number;
  hour: number;
}

/** Props for the drawing of the terrain. */
export interface TerrainStageProps {
  hours: number[][];
  motion: ReturnType<typeof useTerrainMotion>;
  cursor: TerrainCell | null;
  onCursor: (cell: TerrainCell | null) => void;
  /** Names the stage and says how to move around it. */
  label: string;
}

const FLY_ZOOM = 2;
// Flying in also looks further down, so the chosen column is not hidden behind taller ones in front.
const FLY_PITCH = 1.1;

/**
 * The terrain itself: one column per hour, drawn back to front in SVG. A drag
 * turns the camera, a pinch or the plus and minus keys zoom, and a click or
 * Enter flies to a column. Arrows move the highlighted hour, Shift with an
 * arrow turns the camera, and Escape returns to the whole week.
 */
export function TerrainStage({
  hours,
  motion,
  cursor,
  onCursor,
  label,
}: TerrainStageProps) {
  const { frame, aim, nudge, release, target } = motion;
  const drag = useRef<{
    x: number;
    y: number;
    time: number;
    moved: boolean;
  } | null>(null);
  const max = Math.max(1, ...hours.flat());

  const flyTo = (cell: TerrainCell) => {
    const { x, z } = cellCentre(cell.day, cell.hour);
    onCursor(cell);
    aim({
      x,
      z,
      zoom: FLY_ZOOM,
      pitch: Math.max(target.current.pitch, FLY_PITCH),
    });
  };
  const backToWeek = () => {
    onCursor(null);
    aim({ x: 0, z: 0, zoom: WEEK_POSE.zoom });
  };

  const onKeyDown = (event: KeyboardEvent<SVGSVGElement>) => {
    const pose = target.current;
    const at = cursor ?? { day: 0, hour: 9 };
    const move = (cell: TerrainCell) => {
      onCursor(cell);
      // Once the camera has flown in, it follows the highlighted hour.
      if (pose.zoom > 1.5) aim({ ...cellCentre(cell.day, cell.hour) });
    };
    const key = event.key;
    if (event.shiftKey && key.startsWith("Arrow")) {
      if (key === "ArrowLeft") aim({ yaw: pose.yaw + 0.25 });
      else if (key === "ArrowRight") aim({ yaw: pose.yaw - 0.25 });
      else if (key === "ArrowUp") aim({ pitch: pose.pitch + 0.15 });
      else aim({ pitch: pose.pitch - 0.15 });
    } else if (key === "ArrowLeft")
      move({ ...at, hour: cursor ? Math.max(0, at.hour - 1) : at.hour });
    else if (key === "ArrowRight")
      move({ ...at, hour: cursor ? Math.min(23, at.hour + 1) : at.hour });
    else if (key === "ArrowUp")
      move({ ...at, day: cursor ? Math.max(0, at.day - 1) : at.day });
    else if (key === "ArrowDown")
      move({ ...at, day: cursor ? Math.min(6, at.day + 1) : at.day });
    else if (key === "Home") move({ ...at, hour: 0 });
    else if (key === "End") move({ ...at, hour: 23 });
    else if (key === "+" || key === "=") aim({ zoom: pose.zoom * 1.25 });
    else if (key === "-" || key === "_") aim({ zoom: pose.zoom / 1.25 });
    else if (key === "Enter" || key === " ") flyTo(at);
    else if (key === "Escape") backToWeek();
    else return;
    event.preventDefault();
  };

  const cellAt = (element: EventTarget | null): TerrainCell | null => {
    const node =
      element instanceof Element ? element.closest("[data-cell]") : null;
    const value = node?.getAttribute("data-cell");
    if (!value) return null;
    const [day, hour] = value.split("-").map(Number);
    return { day: day ?? 0, hour: hour ?? 0 };
  };

  const onPointerDown = (event: PointerEvent<SVGSVGElement>) => {
    drag.current = {
      x: event.clientX,
      y: event.clientY,
      time: event.timeStamp,
      moved: false,
    };
    event.currentTarget.setPointerCapture(event.pointerId);
  };
  const onPointerMove = (event: PointerEvent<SVGSVGElement>) => {
    const state = drag.current;
    if (!state) {
      if (event.pointerType === "mouse") {
        const cell = cellAt(event.target);
        if (cell && (cell.day !== cursor?.day || cell.hour !== cursor?.hour))
          onCursor(cell);
      }
      return;
    }
    const dx = event.clientX - state.x;
    const dy = event.clientY - state.y;
    if (!state.moved && Math.hypot(dx, dy) < 4) return;
    state.moved = true;
    nudge(-dx * 0.008, dy * 0.005, (event.timeStamp - state.time) / 1000);
    drag.current = {
      x: event.clientX,
      y: event.clientY,
      time: event.timeStamp,
      moved: true,
    };
  };
  const onPointerUp = (event: PointerEvent<SVGSVGElement>) => {
    const state = drag.current;
    drag.current = null;
    if (!state) return;
    if (state.moved) release();
    else {
      // The pointer is captured, so the target is the stage: find the column under the finger instead.
      const cell = cellAt(
        document.elementFromPoint(event.clientX, event.clientY),
      );
      if (cell) flyTo(cell);
    }
  };
  // A trackpad pinch arrives as a wheel event with Control held. A plain wheel scrolls the page.
  const onWheel = (event: WheelEvent<SVGSVGElement>) => {
    if (!event.ctrlKey) return;
    aim({ zoom: target.current.zoom * Math.exp(-event.deltaY * 0.01) });
  };

  const columns = hours
    .flatMap((row, day) =>
      row.map((value, hour) => {
        const height = frame.heights[day * 24 + hour] ?? 0;
        return {
          day,
          hour,
          value,
          ...columnFaces(frame.pose, day, hour, height),
        };
      }),
    )
    .sort((a, b) => a.depth - b.depth);

  const isCursor = (day: number, hour: number) =>
    cursor?.day === day && cursor.hour === hour;
  const showLabels = frame.pose.zoom < 1.6;

  return (
    <svg
      role="application"
      aria-roledescription="terrain"
      aria-label={label}
      tabIndex={0}
      viewBox={`0 0 ${STAGE.width} ${STAGE.height}`}
      className="block h-auto w-full cursor-grab touch-pan-y rounded-xl outline-none select-none focus-visible:ring-2 focus-visible:ring-ring active:cursor-grabbing"
      onKeyDown={onKeyDown}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerCancel={() => (drag.current = null)}
      onPointerLeave={(event) => {
        // A mouse that leaves clears the hover, unless the camera has flown in to that hour.
        if (
          event.pointerType === "mouse" &&
          !drag.current &&
          target.current.zoom <= 1.5
        )
          onCursor(null);
      }}
      onWheel={onWheel}
    >
      {columns.map((column) => {
        const share = column.value / max;
        const faded = cursor !== null && !isCursor(column.day, column.hour);
        // A faded column mixes toward the card instead of turning see-through, so columns behind it stay hidden.
        const colour = faded
          ? `color-mix(in oklch, ${rampColour(share)} 35%, var(--card))`
          : rampColour(share);
        return (
          <g
            key={`${column.day}-${column.hour}`}
            data-cell={`${column.day}-${column.hour}`}
          >
            {column.faces.map((face, index) => (
              <polygon
                key={`${face.kind}-${index}`}
                points={face.points}
                fill={
                  face.kind === "top"
                    ? colour
                    : shade(colour, face.kind === "side" ? 30 : 16)
                }
                stroke={
                  isCursor(column.day, column.hour) && face.kind === "top"
                    ? "var(--foreground)"
                    : "none"
                }
                strokeWidth={2}
                strokeLinejoin="round"
              />
            ))}
          </g>
        );
      })}
      {showLabels ? (
        <g
          aria-hidden="true"
          className="fill-muted-foreground text-xs"
          pointerEvents="none"
        >
          {DAY_SHORT.map((day, index) => {
            const point = project(frame.pose, -12.9, 0, index - 3);
            return (
              <text
                key={day}
                x={point.sx}
                y={point.sy}
                textAnchor="end"
                dominantBaseline="middle"
              >
                {day}
              </text>
            );
          })}
          {[0, 6, 12, 18, 23].map((hour) => {
            const point = project(frame.pose, hour - 11.5, 0, 4.3);
            return (
              <text
                key={hour}
                x={point.sx}
                y={point.sy}
                textAnchor="middle"
                dominantBaseline="hanging"
              >
                {hourLabel(hour)}
              </text>
            );
          })}
        </g>
      ) : null}
    </svg>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

import { useFrameLoop } from "../lib/use-frame-loop";
import { clamp, easeInOut, stepSpring } from "../lib/spring";
import {
  type CameraPose,
  PITCH_LIMITS,
  poseOf,
  springsAt,
  TOP_POSE,
  WEEK_POSE,
} from "./camera";

/** The tallest column, in grid units. */
const TALLEST = 6;
/** How tall every column is in the flat heatmap view. */
const FLAT = 0.05;

/** One frame of the terrain: the camera and every column's height, Monday first, hour by hour. */
export interface TerrainFrame {
  pose: CameraPose;
  heights: number[];
}

const heightsOf = (hours: number[][], flat: boolean) => {
  const max = Math.max(1, ...hours.flat());
  return hours.flat().map((value) => (flat ? FLAT : (value / max) * TALLEST));
};

// Each column waits a little longer than its neighbour on the left and in front, so the heights rise as a wave.
const delayOf = (index: number) =>
  (index % 24) * 0.018 + Math.floor(index / 24) * 0.05;
const GROW_SECONDS = 0.55;

/**
 * Drives the terrain: camera springs that carry momentum after a drag, and
 * columns that rise in a wave whenever the figure or the view changes.
 * With reduced motion every change lands in one frame. Frames run only
 * while `active` is true and something still moves.
 */
export function useTerrainMotion(
  hours: number[][],
  flat: boolean,
  reduceMotion: boolean,
  active: boolean,
) {
  const springs = useRef(springsAt(WEEK_POSE));
  const target = useRef<CameraPose>({ ...WEEK_POSE });
  const angledYaw = useRef(WEEK_POSE.yaw);
  const grow = useRef({
    from: heightsOf(hours, true),
    to: heightsOf(hours, flat),
    elapsed: 0,
  });
  const [frame, setFrame] = useState<TerrainFrame>(() => ({
    pose: { ...WEEK_POSE },
    heights: grow.current.from,
  }));
  const [wake, setWake] = useState(0);

  const aim = useCallback((patch: Partial<CameraPose>) => {
    const next = { ...target.current, ...patch };
    next.pitch = clamp(next.pitch, PITCH_LIMITS[0], PITCH_LIMITS[1]);
    next.zoom = clamp(next.zoom, 0.6, 4);
    next.x = clamp(next.x, -12, 12);
    next.z = clamp(next.z, -3.5, 3.5);
    target.current = next;
    setWake((count) => count + 1);
  }, []);

  /** Moves the camera at once, as a drag does, and keeps the speed for the throw that follows. */
  const nudge = useCallback((yaw: number, pitch: number, seconds: number) => {
    const spring = springs.current;
    spring.yaw.value += yaw;
    spring.pitch.value = clamp(
      spring.pitch.value + pitch,
      PITCH_LIMITS[0],
      PITCH_LIMITS[1],
    );
    if (seconds > 0) {
      spring.yaw.velocity = yaw / seconds;
      spring.pitch.velocity = 0;
    }
    target.current = {
      ...target.current,
      yaw: spring.yaw.value,
      pitch: spring.pitch.value,
    };
    setWake((count) => count + 1);
  }, []);

  /** Lets go of a drag: the turn carries on and slows, like a thrown wheel. */
  const release = useCallback(() => {
    const spring = springs.current;
    target.current = {
      ...target.current,
      yaw: spring.yaw.value + spring.yaw.velocity * 0.18,
    };
    setWake((count) => count + 1);
  }, []);

  // A new figure or view starts the wave again from the heights on screen now.
  useEffect(() => {
    const current = grow.current;
    const shown = current.to.map((to, index) => {
      const from = current.from[index] ?? 0;
      const progress = easeInOut(
        clamp((current.elapsed - delayOf(index)) / GROW_SECONDS, 0, 1),
      );
      return from + (to - from) * progress;
    });
    grow.current = { from: shown, to: heightsOf(hours, flat), elapsed: 0 };
    setWake((count) => count + 1);
  }, [hours, flat]);

  // The flat view looks straight down. Leaving it returns to the angle the person last chose.
  useEffect(() => {
    if (flat) {
      angledYaw.current = target.current.yaw;
      aim(TOP_POSE);
    } else {
      aim({ ...WEEK_POSE, yaw: angledYaw.current });
    }
  }, [flat, aim]);

  const step = (seconds: number) => {
    const spring = springs.current;
    const goal = target.current;
    let moving = false;
    for (const key of ["yaw", "pitch", "zoom", "x", "z"] as const) {
      if (reduceMotion) {
        spring[key].value = goal[key];
        spring[key].velocity = 0;
      } else if (stepSpring(spring[key], goal[key], seconds, 120, 22))
        moving = true;
    }
    const growth = grow.current;
    const last = delayOf(growth.to.length - 1) + GROW_SECONDS;
    growth.elapsed = reduceMotion
      ? last
      : Math.min(last, growth.elapsed + seconds);
    if (growth.elapsed < last) moving = true;
    const heights = growth.to.map((to, index) => {
      const from = growth.from[index] ?? 0;
      return (
        from +
        (to - from) *
          easeInOut(
            clamp((growth.elapsed - delayOf(index)) / GROW_SECONDS, 0, 1),
          )
      );
    });
    setFrame({ pose: poseOf(spring), heights });
    return moving;
  };

  useFrameLoop(step, active, wake);

  return { frame, aim, nudge, release, target };
}

"use client";

import { useEffect, useLayoutEffect, useRef } from "react";

/**
 * Runs `step` once per animation frame while `active` is true. `step` gets the
 * seconds since the last frame, capped so a hidden tab does not jump, and
 * returns false when nothing moves any more, which stops the loop until
 * `wake` changes. The latest `step` always runs, so it may read fresh state.
 */
export function useFrameLoop(
  step: (seconds: number) => boolean,
  active: boolean,
  wake: string | number | null = null,
) {
  const stepRef = useRef(step);
  useLayoutEffect(() => {
    stepRef.current = step;
  });
  useEffect(() => {
    if (!active) return;
    let frame = 0;
    let last = performance.now();
    const tick = (now: number) => {
      const seconds = Math.min(0.05, (now - last) / 1000);
      last = now;
      if (stepRef.current(seconds)) frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [active, wake]);
}

import { Table } from "@/components/ui/table";
import { RollingText } from "../../parts/rolling-text";
import { Delta } from "../../parts/delta";
import { formatWhole } from "../../lib/format";
import { DAYS, hourLabel, type TerrainMetric, readWeek } from "./data";

/**
 * The three figures under the terrain: the week's total with its change,
 * the busiest hour of the day and the busiest day. They say in text what
 * the terrain shows in height.
 */
export function TerrainSummary({ metric }: { metric: TerrainMetric }) {
  const week = readWeek(metric);
  const figures = [
    {
      label: `${metric.label} this week`,
      value: formatWhole(week.total),
      extra: <Delta value={week.change} />,
    },
    {
      label: "Peak hour",
      value: `${hourLabel(week.peakHour)} to ${hourLabel(week.peakHour + 1)}`,
      extra: null,
    },
    {
      label: "Busiest day",
      value: DAYS[week.busiestDay] ?? "",
      extra: (
        <span className="text-xs text-muted-foreground">
          {formatWhole(week.dayTotals[week.busiestDay] ?? 0)} {metric.noun}
        </span>
      ),
    },
  ];
  return (
    <dl className="grid grid-cols-1 gap-px border-t border-border bg-border @md:grid-cols-3">
      {figures.map((figure) => (
        <div
          key={figure.label}
          className="flex flex-col gap-1 bg-card px-5 py-4"
        >
          <dt className="text-sm text-muted-foreground">{figure.label}</dt>
          <dd className="flex flex-wrap items-baseline gap-2">
            <RollingText
              text={figure.value}
              className="text-xl font-semibold tracking-tight"
            />
            {figure.extra}
          </dd>
        </div>
      ))}
    </dl>
  );
}

/** A table of each day's total and busiest hour, for a screen reader in place of the terrain's heights. */
export function TerrainTable({ metric }: { metric: TerrainMetric }) {
  const week = readWeek(metric);
  return (
    <div className="sr-only">
    <Table>
      <caption>
        {metric.label} by day, {formatWhole(week.total)} in total
      </caption>
      <thead>
        <tr>
          <th scope="col">Day</th>
          <th scope="col">Total</th>
          <th scope="col">Busiest hour</th>
        </tr>
      </thead>
      <tbody>
        {metric.hours.map((row, day) => {
          const peak = row.indexOf(Math.max(...row));
          return (
            <tr key={DAYS[day]}>
              <th scope="row">{DAYS[day]}</th>
              <td>{formatWhole(week.dayTotals[day] ?? 0)}</td>
              <td>
                {hourLabel(peak)}, {formatWhole(row[peak] ?? 0)}
              </td>
            </tr>
          );
        })}
      </tbody>
    </Table>
    </div>
  );
}

import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** Props for a formatted figure whose digits roll. */
export interface RollingTextProps {
  /** A figure that is already formatted, such as "$3,577" or "8.2 min". */
  text: string;
  className?: string;
}

/**
 * Shows a formatted figure and rolls each digit to its new value when the
 * text changes, as a counter does. Signs, separators and units stay still.
 * Each glyph is keyed by its place from the right, so a digit keeps its
 * column when the figure grows. It is for text that already has another
 * spoken source: the rolling columns are hidden from screen readers.
 */
export function RollingText({ text, className }: RollingTextProps) {
  const glyphs = [...text];
  return (
    <span className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        {glyphs.map((glyph, index) => {
          const place = glyphs.length - 1 - index;
          return glyph >= "0" && glyph <= "9" ? (
            <NumberTicker key={place} value={Number(glyph)} />
          ) : (
            <span key={place} className="whitespace-pre">
              {glyph}
            </span>
          );
        })}
      </span>
    </span>
  );
}

import { ArrowDownIcon, ArrowUpIcon } from "@/components/blocks/parts/icons";
import { cn } from "@/lib/utils";

import { formatPercent } from "../lib/format";
import { STATUS_TEXT } from "../lib/status";

/** Props for a change figure. */
export interface DeltaProps {
  /** The percent change. */
  value: number;
  /** Set when a fall is the good direction, such as no-shows or waiting time. */
  lowerIsBetter?: boolean;
  className?: string;
}

/**
 * A percent change with an arrow. The arrow and the spoken word carry the
 * direction, and the colour says only whether the change is good.
 */
export function Delta({ value, lowerIsBetter = false, className }: DeltaProps) {
  const flat = Math.abs(value) < 0.05;
  const up = value > 0;
  const good = flat ? null : up !== lowerIsBetter;
  const Arrow = up ? ArrowUpIcon : ArrowDownIcon;
  return (
    <span
      className={cn(
        "inline-flex items-center gap-0.5 text-xs font-medium tabular-nums",
        good === null ? "text-muted-foreground" : STATUS_TEXT[good ? "good" : "bad"],
        className,
      )}
    >
      {flat ? null : <Arrow aria-hidden="true" className="size-3" />}
      <span className="sr-only">{flat ? "No change" : up ? "Up" : "Down"}</span>
      {formatPercent(value)}
    </span>
  );
}

/** The three states a figure or a row can be in. */
export type Status = "good" | "watch" | "bad";

/** The text colour for each state. Each one passes 4.5 to 1 on a card in both themes. */
export const STATUS_TEXT = {
  good: "text-marketing-green-ink",
  watch: "text-marketing-amber-ink",
  bad: "text-marketing-orange-ink",
} satisfies Record<Status, string>;

/** A tinted surface for each state, for a pill or a cell. Pair it with the matching text colour. */
export const STATUS_SURFACE = {
  good: "bg-marketing-green-surface",
  watch: "bg-marketing-amber-surface",
  bad: "bg-marketing-orange-surface",
} satisfies Record<Status, string>;

/** The word a screen reader and a label use for each state. Colour never carries a state alone. */
export const STATUS_WORD = {
  good: "Good",
  watch: "Watch",
  bad: "At risk",
} satisfies Record<Status, string>;

"use client";

import { type RefObject, useEffect, useState } from "react";

/**
 * Says whether the element is on screen, so a showpiece can stop drawing
 * frames while it is scrolled away. It reads false until the first check.
 */
export function useInView(ref: RefObject<Element | null>): boolean {
  const [inView, setInView] = useState(false);
  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    const observer = new IntersectionObserver(
      ([entry]) => setInView(entry?.isIntersecting ?? false),
      { rootMargin: "64px" },
    );
    observer.observe(node);
    return () => observer.disconnect();
  }, [ref]);
  return inView;
}
